<template>
  <section class="operations-page">
    <header class="hero"><div><p class="eyebrow">STORY AGENT · STAGE 7 · MATERIAL OPERATIONS</p><h2>黄金卡与 Domain Pack 总控</h2><p>聚合候选覆盖、真人审稿、Ed25519签名、Domain Pack证据与晋升门禁，为每个外部缺口生成唯一NEXT。</p></div><nav><RouterLink to="/story/stage7-golden-card-review">审稿</RouterLink><RouterLink to="/story/stage7-golden-card-expansion">候选</RouterLink><RouterLink to="/story/stage7-golden-card-signature">签名</RouterLink></nav></header>
    <div class="truth-lock"><strong>外部交接 ≠ 外部完成</strong><span>交接包仅在内存生成；不批准、不晋升、不写回、不启动执行。</span></div>
    <p v-if="errorMessage" class="error-banner">{{ errorMessage }}</p>
    <section v-if="report" class="summary-grid"><article><span>黄金卡候选</span><strong>{{ report.summary.golden_card_indexed_candidate_count }}/75</strong></article><article><span>覆盖片型</span><strong>{{ report.summary.covered_video_type_count }}/15</strong></article><article><span>候选槽位</span><strong>{{ report.summary.planned_candidate_slot_count }}</strong></article><article><span>Domain Pack</span><strong>{{ report.summary.domain_pack_candidate_count }}/9</strong></article><article><span>外部NEXT</span><strong>{{ report.summary.external_handoff_task_count }}</strong></article><article class="zero"><span>人工通过 / 晋升</span><strong>0 / 0</strong></article></section>
    <section v-if="report" class="lane-grid"><article v-for="lane in report.lanes" :key="lane.lane_id"><header><span>{{ lane.label }}</span><b>{{ lane.current_count }}/{{ lane.target_count }}</b></header><div class="bar"><i :style="{width:`${lane.target_count?lane.current_count/lane.target_count*100:0}%`}"/></div><p>{{ lane.next_action }}</p><small>{{ lane.blocker_count }} blockers · {{ lane.status }}</small></article></section>
    <section v-if="report" class="main-grid">
      <article class="task-card"><header><div><p class="eyebrow">EXTERNAL NEXT QUEUE</p><h3>51项确定外部动作</h3></div><div class="filters"><select v-model="scopeFilter"><option value="all">全部范围</option><option value="video_type">片型</option><option value="golden_card">黄金卡</option><option value="domain_pack">Domain Pack</option></select><select v-model="priorityFilter"><option value="all">全部优先级</option><option value="p0">P0</option><option value="p1">P1</option><option value="p2">P2</option></select></div></header><div class="task-list"><article v-for="task in filteredTasks" :key="task.task_id"><div><b :class="task.priority">{{ task.priority.toUpperCase() }}</b><span>{{ scopeLabel(task.scope) }}</span><code>{{ task.target_id }}</code></div><h4>{{ task.label }}</h4><p>NEXT · {{ actionLabel(task.next_action) }}</p><small>missing_external_input · 不计完成</small></article></div></article>
      <article class="handoff-card"><header><div><p class="eyebrow">MEMORY-ONLY HANDOFF</p><h3>外部交接 JSON</h3></div><button @click="copyHandoff">{{ copyMessage||'复制 JSON' }}</button></header><textarea :value="handoffJson" aria-label="Stage 7 external handoff JSON" readonly/><div class="safety-grid"><span>Persisted <b>否</b></span><span>Execution started <b>否</b></span><span>Human approval <b>否</b></span><span>Golden promoted <b>否</b></span><span>Domain Pack promoted <b>否</b></span><span>Professional passed <b>否</b></span></div></article>
    </section>
  </section>
</template>

<script setup lang="ts">
import { computed,onMounted,ref } from 'vue'
import type { Stage7MaterialOperationsReport } from '@shared/types'
import { getStage7MaterialOperations } from '../api/stage7-golden-cards'
const report=ref<Stage7MaterialOperationsReport|null>(null),errorMessage=ref(''),copyMessage=ref(''),scopeFilter=ref('all'),priorityFilter=ref('all')
const filteredTasks=computed(()=>report.value?.tasks.filter(task=>(scopeFilter.value==='all'||task.scope===scopeFilter.value)&&(priorityFilter.value==='all'||task.priority===priorityFilter.value))??[])
const handoffJson=computed(()=>report.value?`${JSON.stringify(report.value.handoff_package,null,2)}\n`:'')
onMounted(async()=>{const response=await getStage7MaterialOperations();if(!response.ok||!response.data){errorMessage.value=response.error?.message??'Stage 7总控加载失败';return}report.value=response.data})
async function copyHandoff(){try{await navigator.clipboard.writeText(handoffJson.value);copyMessage.value='已复制'}catch{copyMessage.value='复制未授权'}window.setTimeout(()=>copyMessage.value='',1600)}
function scopeLabel(value:string){return {video_type:'片型候选',golden_card:'黄金卡审稿',domain_pack:'Domain Pack'}[value]??value} function actionLabel(value:string){return {complete_candidate_content_and_source_evidence:'补齐候选内容与来源证据',complete_external_role_reviews:'完成风险角色实名审稿',complete_real_domain_pack_evidence_and_review:'完成真实证据槽位、审稿与签名'}[value]??value}
</script>

